/* Proposed data flywheel. Interactive explanations, no training or robot backend. */
function renderDataFlywheel(){
 const positions=[[50,12],[83,31],[83,69],[50,88],[17,69],[17,31]];
 return head('DATA CORE · DATA FLYWHEEL','Mỗi lượt chạy cho biết<br>lần học tiếp theo cần gì.','Chọn tín hiệu cần học rồi chọn cách thu hoặc sinh dữ liệu. Trải nghiệm thực thi, bằng chứng và kiểm chứng đóng vòng để chọn dữ liệu có ích cho kỹ năng.')+
 `<p class="fly-status">Thiết kế đề xuất · Các tình huống tương tác là ví dụ, chưa là kết quả native VLA.</p><section class="fly-layout"><div class="fly-wheel" role="group" aria-label="Sáu bước data flywheel"><svg viewBox="0 0 600 520" aria-hidden="true"><defs><marker id="fly-arrow" viewBox="0 0 10 10" refX="8" refY="5" markerWidth="5" markerHeight="5" orient="auto-start-reverse"><path d="M0 0L10 5L0 10Z" fill="#bd2235"/></marker></defs><path d="M333 68 Q430 60 482 126 M515 207 L515 295 M482 396 Q426 460 338 455 M266 455 Q165 460 115 396 M85 300 L85 211 M118 126 Q170 64 263 68" fill="none" stroke="#bd2235" stroke-width="3" marker-end="url(#fly-arrow)"/></svg><div class="fly-center"><span>DATA CORE</span><strong>Dữ liệu đúng<br>cho lần học tới</strong><small>Kỹ sư quyết định<br>Kiểm chứng trước promote</small></div>${FLYWHEEL_DATA.steps.map((s,i)=>`<button type="button" class="fly-node" data-fly-step="${i}" style="left:${positions[i][0]}%;top:${positions[i][1]}%" aria-pressed="${i===0}" aria-controls="fly-detail"><span>0${i+1}</span><strong>${esc(s.short)}</strong></button>`).join('')}</div><article id="fly-detail" class="panel fly-detail" aria-live="polite"></article></section>`+
 `<section class="panel fly-scenarios"><div class="eyebrow">CÙNG MỘT VÒNG LẶP · CAN THIỆP KHÁC NHAU</div><h2>Robot lỗi, có phải luôn thu thêm data?</h2><div class="fly-case-tabs" role="group" aria-label="Tình huống minh họa">${FLYWHEEL_DATA.cases.map((c,i)=>`<button type="button" data-fly-case="${i}" aria-pressed="${i===0}" aria-controls="fly-case-detail">${esc(c.label)}</button>`).join('')}</div><div id="fly-case-detail" aria-live="polite"></div></section>`+
 section('Ba supervision views, mỗi view có việc riêng')+`<div class="cards">${FLYWHEEL_DATA.sources.map(s=>card(s.id,s.title,esc(s.body))).join('')}</div>`+
 `<section class="panel spaced"><h2>Flywheel tích lũy điều gì?</h2><p>Trải nghiệm có nguồn gốc, demonstrations đủ nhãn, coverage đã thử, recipes và cả can thiệp không hiệu quả. Phiên bản tốt hơn có thể tạo trải nghiệm mới; gain không được bảo đảm qua mỗi vòng.</p><p><strong>Đo giá trị:</strong> chất lượng cả task và regression; robot-data usage; tổng công tới nghiệm thu; mức tái sử dụng ở task kế tiếp. Số video và số vòng lặp chưa chứng minh tiết kiệm.</p><p>R/R+S và R_common/R_common+H là source pilots. Vòng acquisition thích nghi cần phép so riêng với workflow kỹ sư thông thường, cùng khả năng can thiệp và ngân sách.</p></section>`+
 acquisitionReceiptView()+
 `<details class="technical-detail"><summary>Đọc chi tiết: QA, recovery, holdout và các hợp đồng</summary><div class="detail-body"><article class="document-reader">${renderMarkdown(DOSSIER.find(d=>d.path===ENGINEERING_DIR+'03-workflow-du-lieu.md').markdown,ENGINEERING_DIR+'03-workflow-du-lieu.md')}</article><article class="document-reader">${renderMarkdown(DOSSIER.find(d=>d.path===ENGINEERING_DIR+'11-contracts-va-logic.md').markdown,ENGINEERING_DIR+'11-contracts-va-logic.md')}</article></div></details>`+next('learning','Xem cách robot học');
}
function initDataFlywheel(signal){
 const detail=document.querySelector('#fly-detail');if(!detail)return;
 const showStep=i=>{const s=FLYWHEEL_DATA.steps[i];detail.innerHTML=`<div class="eyebrow">BƯỚC 0${i+1} / 06</div><h2>${esc(s.title)}</h2><p>${esc(s.body)}</p><div class="fly-output"><strong>Đầu ra cần có</strong><p>${esc(s.output)}</p></div><p class="fly-gate"><strong>Điều kiện:</strong> ${esc(s.gate)}</p><button class="button fly-next" type="button" data-fly-next="${(i+1)%6}">${i===5?'Trở lại lượt chạy':'Bước tiếp theo'} →</button>`;document.querySelectorAll('[data-fly-step]').forEach(b=>b.setAttribute('aria-pressed',String(Number(b.dataset.flyStep)===i)));};
 const showCase=i=>{const c=FLYWHEEL_DATA.cases[i];document.querySelector('#fly-case-detail').innerHTML=`<p class="fly-case-fact">${esc(c.fact)}</p>${table(['Phần của vòng lặp','Quyết định minh họa'],[['Kiểm giả thuyết',esc(c.test)],['Can thiệp',esc(c.choice)],['Dữ liệu / release',esc(c.data)],['Kiểm lại',esc(c.check)]])}`;document.querySelectorAll('[data-fly-case]').forEach(b=>b.setAttribute('aria-pressed',String(Number(b.dataset.flyCase)===i)));};
 document.querySelector('main').addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.flyStep!==undefined)showStep(Number(b.dataset.flyStep));if(b.dataset.flyNext!==undefined)showStep(Number(b.dataset.flyNext));if(b.dataset.flyCase!==undefined)showCase(Number(b.dataset.flyCase));},{signal});showStep(0);showCase(0);
}
